import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val grades = mutableListOf<Double>()

    println("Enter grades (type 'done' when finished):")
    while (true) {
        print("Grade: ")
        val input = scanner.nextLine()
        if (input.lowercase() == "done") break
        try {
            val grade = input.toDouble()
            grades.add(grade)
        } catch (e: NumberFormatException) {
            println("Invalid grade. Please enter a numeric value.")
        }
    }

    if (grades.isEmpty()) {
        println("No grades entered.")
        return
    }

    val average = grades.average()
    println("Average grade: $average")
}

import kotlin.math.roundToInt

fun calculateAverageGrades(input: List<String>): Int {
    val grades = input.mapNotNull { it.toIntOrNull() }
    val sum = grades.sum()
    val count = grades.size
    return if (count > 0) (sum.toDouble() / count).roundToInt() else 0
}

